def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    # Tally outcomes and opponent behavior cheaply.
    opp_def = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_def += 1
    opp_coop = n - opp_def
    coop_rate = opp_coop / n

    # Recent windows.
    w10 = 10 if n >= 10 else n
    recent_opp_def = 0
    for i in range(n - w10, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    w5 = 5 if n >= 5 else n
    recent_opp_def5 = 0
    for i in range(n - w5, n):
        if history[i][1] == 'D':
            recent_opp_def5 += 1

    # Detect current defection streak.
    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    # Very cooperative opponent: lock in mutual cooperation.
    if coop_rate >= 0.9 and streak == 0:
        return 'C'

    # Strongly exploitative opponent: defect hard.
    if coop_rate <= 0.25:
        return 'D'

    if streak >= 3:
        # Long defection streak: punish, but probe near the end less.
        if n < 95 and streak >= 5 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Endgame exploitation against cooperative opponents.
    if n >= 96:
        if coop_rate >= 0.5:
            return 'D'
        if opp_last == 'C':
            return 'D'
        return 'D'

    if n >= 90:
        if coop_rate >= 0.7:
            return 'D'
        if opp_last == 'C':
            return 'C'
        return 'D'

    # Punish isolated recent defections but forgive quickly.
    if opp_last == 'D':
        if my_last == 'D':
            return 'D' if rng.random() < 0.6 else 'C'
        # We cooperated and got exploited.
        if recent_opp_def5 >= 3:
            return 'D'
        if coop_rate > 0.6 and rng.random() < 0.5:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if my_last == 'D':
        # Return to cooperation after our defection, unless they are
        # punishing us with a streak.
        if recent_opp_def5 >= 3:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    # Both cooperated: default cooperate, with rare safe probing.
    if recent_opp_def >= 4:
        return 'D'
    if coop_rate < 0.5 and rng.random() < 0.2:
        return 'D'
    return 'C'
